def balanced_ternary_str(n: int) -> str:
    if n == 0:
        return "0"
    digits = []
    while n != 0:
        remainder = n % 3
        if remainder == 0:
            digits.append('0')
            n //= 3
        elif remainder == 1:
            digits.append('+')
            n = (n - 1) // 3
        else:  # remainder == 2
            digits.append('-')
            n = (n + 1) // 3
    return ''.join(reversed(digits))
```

