def is_monotonic(nums: list[int]) -> bool:
    if not nums:
        return True
    increasing = all(nums[i] <= nums[i+1] for i in range(len(nums)-1))
    decreasing = all(nums[i] >= nums[i+1] for i in range(len(nums)-1))
    return increasing or decreasing

