def count_interval_overlaps(intervals: list[tuple[int, int]]) -> int:
    if not intervals:
        return 0
    # Sort intervals by their start time
    sorted_intervals = sorted(intervals, key=lambda x: x[0])
    count = 0
    # Use a stack to track the current intervals
    stack = [sorted_intervals[0]]
    for interval in sorted_intervals[1:]:
        # Check for overlap with the last interval in the stack
        if interval[0] <= stack[-1][1]:
            count += 1
        else:
            stack.append(interval)
    return count

