import subprocess
import os

def make_tar(directory: str, archive_path: str) -> str:
    if not os.path.exists(directory):
        raise FileNotFoundError(f"The directory {directory} does not exist.")
    if os.path.exists(archive_path):
        raise FileExistsError(f"The archive file {archive_path} already exists.")

    # Use the system's tar command to create the archive
    subprocess.run(['tar', '-cf', archive_path, '-C', directory, '.'], check=True)
    return archive_path

