def matrix_power_mod(matrix: list[list[int]], exp: int, mod: int) -> list[list[int]]:
    n = len(matrix)
    # Function to multiply two matrices under mod
    def multiply(a, b):
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            for k in range(n):
                if a[i][k]:
                    for j in range(n):
                        result[i][j] = (result[i][j] + a[i][k] * b[k][j]) % mod
        return result

    # Function to compute matrix^exp using binary exponentiation
    def matrix_pow(mat, power):
        # Initialize result as identity matrix
        result = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
        while power > 0:
            if power % 2 == 1:
                result = multiply(result, mat)
            mat = multiply(mat, mat)
            power //= 2
        return result

    return matrix_pow(matrix, exp)
