                while i < len(encoded) and encoded[i].isdigit():
                    repeat_count = repeat_count * 10 + int(encoded[i])
                    i += 1
                if i < len(encoded):
                    char = encoded[i]
                    result.append(char * repeat_count)
                    i += 1
            else:
                # Handle single character case
