def matrix_power_mod(matrix: list[list[int]], exp: int, mod: int) -> list[list[int]]:
    n = len(matrix)
    # Function to multiply two matrices under mod
    def multiply(a, b):
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            for k in range(n):
                if a[i][k]:
                    for j in range(n):
                        result[i][j] = (result[i][j] + a[i][k] * b[k][j]) % mod
        return result

    # Function to square a matrix (used in exponentiation by squaring)
    def square(mat):
        return multiply(mat, mat)

    # Identity matrix
    def identity():
        return [[1 if i == j else 0 for j in range(n)] for i in range(n)]

    # Handle exponent 0 case
    if exp == 0:
        return identity()

    # Initialize result as identity matrix
    result = identity()
    current = matrix

    # Exponentiation by squaring
    while exp > 1:
        if exp % 2 == 0:
            current = square(current)
            exp //= 2
        else:
            result = multiply(result, current)
            current = square(current)
            exp = (exp - 1) // 2

    # Final multiplication
    result = multiply(result, current)

    return result
