def matrix_power_mod(matrix: list[list[int]], exp: int, mod: int) -> list[list[int]]:
    n = len(matrix)
    # Function to multiply two matrices under mod
    def multiply(a, b):
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            for k in range(n):
                if a[i][k]:
                    for j in range(n):
                        result[i][j] = (result[i][j] + a[i][k] * b[k][j]) % mod
        return result

    # Function to square a matrix (used in exponentiation by squaring)
    def square(mat):
        return multiply(mat, mat)

    # Function to compute matrix^exp using exponentiation by squaring
    def matrix_pow(mat, power):
        result = [[1 if i == j else 0 for j in range(n)] for i in range(n)]  # Identity matrix
        while power > 0:
            if power % 2 == 1:
                result = multiply(result, mat)
            mat = square(mat)
            power //= 2
        return result

    return matrix_pow(matrix, exp)
