def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    if n == 0:
        return 1

    blocked_set = set((r, c) for r, c in blocked if 0 <= r < n and 0 <= c < n)

    def is_safe(board, row, col):
        for i in range(n):
            if board[i][col] or (abs(i - row) == abs(board[i][col] - col)):
                return False
        return True

    def backtrack(queens, board):
        if len(queens) == n:
            return 1
        count = 0
        for col in range(n):
            row = len(queens)
            if (row, col) in blocked_set:
                continue
            if is_safe(board, row, col):
                board[row][col] = 1
                count += backtrack(queens + [(row, col)], board)
                board[row][col] = 0
        return count

    board = [[0 for _ in range(n)] for _ in range(n)]
    return backtrack([], board)
