from typing import List, Tuple
from collections import defaultdict

def find_bridges(n: int, edges: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n
    disc = [float('inf')] * n
    low = [float('inf')] * n
    time = [0]
    bridges = []

    def dfs(u, parent):
        visited[u] = True
        disc[u] = low[u] = time[0]
        time[0] += 1
        for v in graph[u]:
            if v == parent:
                continue
            if not visited[v]:
                dfs(v, u)
                low[u] = min(low[u], low[v])
                if low[v] > disc[u]:
                    bridges.append((u, v) if u < v else (v, u))
            else:
                low[u] = min(low[u], disc[v])

    for i in range(n):
        if not visited[i]:
            dfs(i, -1)

    bridges.sort()
    return bridges
