                    grid[r][c] -= 4
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            grid[nr][nc] += 1
        if not toppling:
            break

    return grid
