from collections import deque, defaultdict

def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    if source == target:
        return 1

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    dist = [-1] * n
    prev = defaultdict(list)
    q = deque()
    q.append(source)
    dist[source] = 0

    while q:
        u = q.popleft()
        for v in graph[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                prev[v] = [u]
                q.append(v)
            elif dist[v] == dist[u] + 1:
                prev[v].append(u)

    if dist[target] == -1:
        return 0

    count = 1
    current = target
    while current != source:
        current = prev[current][0]
        count *= len(prev[current])

    return count

