import re

def is_valid_email(s: str) -> bool:
    if s.count('@') != 1:
        return False

    local, domain = s.split('@', 1)

    # Validate local part
    if not re.fullmatch(r'[a-zA-Z0-9][a-zA-Z0-9._-]*[a-zA-Z0-9]', local):
        return False
    if re.search(r'_{2}|-{2}|\.{2}', local):
        return False

    # Validate domain part
    domain_parts = domain.split('.')
    if len(domain_parts) < 2:
        return False

    for part in domain_parts[:-1]:
        if not re.fullmatch(r'[a-zA-Z0-9]+', part):
            return False

    last_part = domain_parts[-1]
    if not re.fullmatch(r'[a-zA-Z]{2,}', last_part):
        return False

    return True
