def decode_runs(encoded: str) -> str:
    result = []
    i = 0
    while i < len(encoded):
        if encoded[i] == '\\':
            # Escaped character, add it once
            result.append(encoded[i + 1])
            i += 2
        elif encoded[i] == '~':
            # Check if there's a number following
            if i + 1 < len(encoded) and encoded[i + 1].isdigit():
                # Find the end of the number
                j = i + 1
                while j < len(encoded) and encoded[j].isdigit():
                    j += 1
                count = int(encoded[i + 1:j])
                # Add the previous character count times
                if count > 0:
                    result.append(encoded[i - 1] * count)
                i = j
            else:
                # Invalid format, but the input is guaranteed to be well-formed
                i += 1
        else:
            # Regular character, add it once
            result.append(encoded[i])
            i += 1
    return ''.join(result)
