from urllib.parse import urlparse

def is_local_redirect(target: str, host: str) -> bool:
    # Check for invalid characters
    if any(c < 32 or c == 127 for c in target):
        return False

    # Case 1: Site-relative path (starts with '/' and not a full path)
    if target.startswith('/') and len(target) > 1 and target[1] != '/':
        return True

    # Case 2: URL with matching hostname
    if target.startswith('http://') or target.startswith('https://'):
        parsed = urlparse(target)
        netloc = parsed.netloc
        if not netloc:
            return False
        # Extract hostname, ignoring port and user info
        hostname = re.sub(r'^[^@]+@', '', netloc).split(':', 1)[0]
        return hostname.lower() == host.lower()

    return False

