def pack_bins(sizes: list[int], capacity: int) -> list[list[int]]:
    if not sizes:
        return []

    # Check for any item larger than capacity
    for size in sizes:
        if size > capacity:
            raise ValueError("All item sizes must be less than or equal to the capacity.")

    # Sort sizes in decreasing order
    sizes.sort(reverse=True)

    # Initialize list of bins
    bins = []

    for size in sizes:
        placed = False
        for bin in bins:
            if sum(bin) + size <= capacity:
                bin.append(size)
                placed = True
                break
        if not placed:
            bins.append([size])

    return bins
