import re
from urllib.parse import urlparse

def is_local_redirect(target: str, host: str) -> bool:
    # Check for invalid characters
    if re.search(r'[\x00-\x1f\x7f]', target):
        return False

    # Case 1: Site-relative path (starts with exactly one '/')
    if len(target) >= 1 and target[0] == '/' and (len(target) == 1 or target[1] != '/'):
        return True

    # Case 2: Absolute URL with matching host
    try:
        parsed = urlparse(target)
        if parsed.scheme not in ('http', 'https'):
            return False
        netloc = parsed.netloc
        if not netloc:
            return False
        # Extract host name (without port and user info)
        host_parts = netloc.split('@')
        if len(host_parts) > 1:
            netloc = host_parts[1]
        host_parts = netloc.split(':')
        if len(host_parts) > 1:
            netloc = host_parts[0]
        return host.lower() == netloc.lower()
    except:
        return False
```

