def pack_bins(sizes: list[int], capacity: int) -> list[list[int]]:
    if not sizes:
        return []

    # Check for any size larger than capacity
    for size in sizes:
        if size > capacity:
            raise ValueError("All sizes must be less than or equal to capacity.")

    # Sort sizes in descending order
    sizes.sort(reverse=True)

    # List to hold the bins
    bins = []

    for size in sizes:
        placed = False
        # Try to place in existing bins
        for i in range(len(bins)):
            if sum(bins[i]) + size <= capacity:
                bins[i].append(size)
                placed = True
                break
        # If not placed, create a new bin
        if not placed:
            bins.append([size])

    return bins
