import re

def tidy_punctuation(text: str) -> str:
    # Step 1: Replace sequences of whitespace with a single space and strip leading/trailing spaces
    text = re.sub(r'\s+', ' ', text).strip()

    # Step 2: Remove space followed by one of the punctuation characters
    text = re.sub(r' ([,.:;!?])', r'\1', text)

    # Step 3: Insert a space after each of the punctuation characters followed by a letter
    text = re.sub(r'([,.:;!?])(?=[a-zA-Z])', r'\1 ', text)

    # Step 4: Capitalize the first character and any character after . ! ?
    # First, find all positions to capitalize
    capitalize_positions = set()
    # Check for characters after . ! ? followed by a space
    for i in range(len(text) - 1):
        if text[i] in '.!?':
            if i + 1 < len(text) and text[i + 1] == ' ':
                if i + 2 < len(text):
                    capitalize_positions.add(i + 2)
    # Also capitalize the first character
    if text:
        capitalize_positions.add(0)
    # Apply capitalization
    result = []
    for i, char in enumerate(text):
        if i in capitalize_positions:
            if char.isalpha():
                result.append(char.upper())
            else:
                result.append(char)
        else:
            result.append(char)
    return ''.join(result)
