def free_slots(busy: list[tuple[int, int]], day_start: int, day_end: int, min_len: int) -> list[tuple[int, int]]:
    if day_start >= day_end:
        return []

    # Filter out invalid busy intervals
    busy = [(s, e) for s, e in busy if s < e]
    # Sort busy intervals by start time
    busy.sort()

    # Initialize free slots list
    free_slots = []
    prev_end = day_start

    for start, end in busy:
        # Check if the current busy interval is within the day
        if start >= day_end:
            continue
        if end > day_end:
            end = day_end

        # Check if there is a free gap between prev_end and start
        if prev_end < start:
            gap = start - prev_end
            if gap >= min_len:
                free_slots.append((prev_end, start))

        # Update prev_end to the end of the current busy interval
        prev_end = max(prev_end, end)

    # Check the gap after the last busy interval
    if prev_end < day_end:
        gap = day_end - prev_end
        if gap >= min_len:
            free_slots.append((prev_end, day_end))

    return free_slots

