from urllib.parse import urlparse

def fetch_target_allowed(url: str, allowed_hosts: list[str]) -> bool:
    parsed = urlparse(url)
    if parsed.scheme not in ('http', 'https'):
        return False
    if '@' in parsed.netloc:
        return False
    host = parsed.netloc.split(':', 1)[0].lower()
    if host.endswith('.'):
        host = host[:-1]
    allowed_hosts_lower = [h.lower() for h in allowed_hosts]
    return host in allowed_hosts_lower

