from collections import deque
import sys

def min_slides(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    start, end = None, None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if not start or not end:
        return -1

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = set()
    queue = deque([(start[0], start[1], 0)])
    visited.add((start[0], start[1]))

    while queue:
        x, y, moves = queue.popleft()

        for dx, dy in directions:
            nx, ny = x, y
            while 0 <= nx + dx < rows and 0 <= ny + dy < cols:
                nx += dx
                ny += dy
            if (nx, ny) == (x, y):
                continue
            if grid[nx][ny] == '#' or (nx, ny) in visited:
                continue
            if (nx, ny) == end:
                return moves + 1
            visited.add((nx, ny))
            queue.append((nx, ny, moves + 1))

    return -1
