def free_slots(busy: list[tuple[int, int]], day_start: int, day_end: int, min_len: int) -> list[tuple[int, int]]:
    if day_start >= day_end:
        return []

    # Sort busy intervals by start time
    busy.sort()
    free_intervals = []

    # Initialize with the day's start
    current_start = day_start
    current_end = day_start

    for start, end in busy:
        # Skip invalid intervals
        if start >= end:
            continue

        # Check if the current interval overlaps with the busy interval
        if start > current_end:
            # There is a free interval between current_end and start
            if start - current_end >= min_len:
                free_intervals.append((current_end, start))
            current_start = start
            current_end = end
        else:
            # Merge with the current busy interval
            current_end = max(current_end, end)

    # Check the last interval
    if current_end < day_end:
        if day_end - current_end >= min_len:
            free_intervals.append((current_end, day_end))

    return free_intervals
