def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not number or number == '-' or not all(c in '0123456789abcdefghijklmnopqrstuvwxyz' for c in number.lower()):
        raise ValueError

    # Handle negative numbers
    is_negative = number[0] == '-'
    if is_negative:
        number = number[1:]

    # Convert from base 'from_base' to decimal
    decimal_value = 0
    for digit in number:
        if digit.isdigit():
            digit_value = int(digit)
        else:
            digit_value = ord(digit.lower()) - ord('a') + 10
        decimal_value = decimal_value * from_base + digit_value

    # Handle zero case
    if decimal_value == 0:
        return "0"

    # Convert from decimal to base 'to_base'
    digits = []
    while decimal_value > 0:
        remainder = decimal_value % to_base
        if remainder < 10:
            digits.append(str(remainder))
        else:
            digits.append(chr(ord('a') + remainder - 10))
        decimal_value //= to_base

    # Reverse to get the correct order
    digits.reverse()

    # Apply negative sign if needed
    if is_negative:
        return '-' + ''.join(digits)
    else:
        return ''.join(digits)
