import math
import re
import ast

def evaluate_formula(formula: str, x: float) -> float:
    # Replace 'x' with the variable name used in the AST
    formula = formula.replace('x', 'var')

    # Define a custom function to evaluate the formula
    def eval_with_var(node):
        if isinstance(node, ast.Expression):
            return eval_with_var(node.body)
        elif isinstance(node, ast.UnaryOp):
            op = node.op
            if isinstance(op, ast.USub):
                return -eval_with_var(node.operand)
            else:
                raise ValueError("Unsupported unary operation")
        elif isinstance(node, ast.BinOp):
            left = eval_with_var(node.left)
            right = eval_with_var(node.right)
            op = node.op
            if isinstance(op, ast.Add):
                return left + right
            elif isinstance(op, ast.Sub):
                return left - right
            elif isinstance(op, ast.Mult):
                return left * right
            elif isinstance(op, ast.Div):
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                return left / right
            elif isinstance(op, ast.Pow):
                return left ** right
            else:
                raise ValueError("Unsupported binary operation")
        elif isinstance(node, ast.Call):
            func = node.func
            if isinstance(func, ast.Name):
                func_name = func.id
                if func_name == 'sqrt':
                    arg = eval_with_var(node.args[0])
                    return math.sqrt(arg)
                elif func_name == 'abs':
                    arg = eval_with_var(node.args[0])
                    return abs(arg)
                elif func_name == 'sin':
                    arg = eval_with_var(node.args[0])
                    return math.sin(arg)
                elif func_name == 'cos':
                    arg = eval_with_var(node.args[0])
                    return math.cos(arg)
                else:
                    raise ValueError(f"Unknown function: {func_name}")
            else:
                raise ValueError("Unsupported function call")
        elif isinstance(node, ast.Name):
            if node.id == 'var':
                return x
            else:
                raise ValueError(f"Unknown variable: {node.id}")
        elif isinstance(node, ast.Num):
            return node.n
        else:
            raise ValueError("Unsupported node type")

    # Check if the formula contains only allowed characters
    if not re.fullmatch(r'[x0-9.+\-*/\(\)\s\*\*sqrtabsinsin cos]+', formula):
        raise ValueError("Invalid formula: contains forbidden characters")

    try:
        # Parse the formula into an AST
        tree = ast.parse(formula, mode='eval')
        # Evaluate the AST
        result = eval_with_var(tree)
        return float(result)
    except (SyntaxError, ValueError, ZeroDivisionError) as e:
        raise ValueError("Invalid formula") from e
