def evaluate_formula(formula: str, x: float) -> float:
    # Replace 'x' with the actual value
    formula = formula.replace('x', str(x))

    # Define a custom function for each allowed mathematical function
    def sqrt_func(arg):
        return math.sqrt(float(arg))

    def abs_func(arg):
        return abs(float(arg))

    def sin_func(arg):
        return math.sin(float(arg))

    def cos_func(arg):
        return math.cos(float(arg))

    # Replace function calls with their corresponding calls
    formula = re.sub(r'sqrt\(([^)]+)\)', r'sqrt_func(\1)', formula)
    formula = re.sub(r'abs\(([^)]+)\)', r'abs_func(\1)', formula)
    formula = re.sub(r'sin\(([^)]+)\)', r'sin_func(\1)', formula)
    formula = re.sub(r'cos\(([^)]+)\)', r'cos_func(\1)', formula)

    # Attempt to parse and evaluate the formula
    try:
        # Use ast to safely evaluate the expression
        node = ast.parse(formula, mode='eval')
