import math
import re
import ast

def evaluate_formula(formula: str, x: float) -> float:
    # Replace 'x' with the actual value
    formula = formula.replace('x', str(x))

    # Check for invalid characters (anything not x, numbers, operators, parentheses, or function names)
    if re.search(r'[^0-9.+\-*/\(\)\s\w\s\-\+]', formula):
        raise ValueError("Invalid characters in formula")

    # Check for invalid function names
    if re.search(r'\b(sin|cos|sqrt|abs)\b', formula):
        pass
    else:
        raise ValueError("Formula must contain only sin, cos, sqrt, and abs functions")

    # Check for invalid variable names (only 'x' is allowed)
    if re.search(r'\b[^x]\b', formula):
        raise ValueError("Formula contains invalid variable names")

    # Attempt to parse the formula using AST
    try:
        tree = ast.parse(formula, mode='eval')
    except SyntaxError:
        raise ValueError("Invalid syntax in formula")

    # Replace function calls with their math equivalents
    def replace_functions(node):
        if isinstance(node, ast.Call):
            if isinstance(node.func, ast.Name):
                func_name = node.func.id
                if func_name == 'sin':
                    return ast.UnaryOp(op=ast.USub(), operand=ast.Call(func=ast.Name(id='sin', ctx=ast.Load()), args=[node.args[0]], keywords=[]))
                elif func_name == 'cos':
                    return ast.UnaryOp(op=ast.USub(), operand=ast.Call(func=ast.Name(id='cos', ctx=ast.Load()), args=[node.args[0]], keywords=[]))
                elif func_name == 'sqrt':
                    return ast.Call(func=ast.Name(id='math.sqrt', ctx=ast.Load()), args=[node.args[0]], keywords=[])
                elif func_name == 'abs':
                    return ast.Call(func=ast.Name(id='abs', ctx=ast.Load()), args=[node.args[0]], keywords=[])
                else:
                    raise ValueError(f"Unknown function: {func_name}")
        return node

    # Traverse the AST and replace function calls
    for node in ast.walk(tree):
        if isinstance(node, ast.Call):
            node.func = replace_functions(node.func)

    # Evaluate the modified AST
    try:
        result = eval(compile(tree, '<string>', 'eval'), {'math': math, 'abs': abs, 'sin': math.sin, 'cos': math.cos, 'sqrt': math.sqrt})
    except ZeroDivisionError:
        raise ZeroDivisionError("Division by zero")
    except Exception as e:
        raise ValueError("Invalid formula") from e

    return float(result)
