def schedule_jobs(jobs: list[tuple[str, int, int]]) -> list[str]:
    # Sort jobs by profit descending, then by original order for ties
    sorted_jobs = sorted(jobs, key=lambda x: (-x[2], jobs.index(x)))
    scheduled = {}
    for name, deadline, _ in sorted_jobs:
        if deadline < 1:
            continue
        # Find the highest-numbered free slot <= deadline
        slot = deadline
        while slot in scheduled:
            slot -= 1
        if slot >= 1:
            scheduled[slot] = name
    # Return list of names ordered by slot number
    return [name for slot, name in sorted(scheduled.items())]
