def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    # Determine column widths
    col_widths = [max(len(cell) for cell in col) for col in zip(*rows)]

    def format_cell(cell: str, align: str, width: int) -> str:
        padding = width - len(cell)
        if align == 'l':
            return cell + ' ' * padding
        elif align == 'r':
            return ' ' * padding + cell
        elif align == 'c':
            left_pad = padding // 2
            right_pad = padding - left_pad
            return ' ' * left_pad + cell + ' ' * right_pad

    # Format each row
    formatted_rows = []
    for i, row in enumerate(rows):
        formatted_row = ' | '.join(format_cell(row[j], aligns[j], col_widths[j]) for j in range(len(row)))
        formatted_rows.append(formatted_row)

    return '\n'.join(formatted_rows)
