from collections import deque
import sys

def min_slides(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    start, end = None, None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if not start or not end:
        return -1

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = set()
    queue = deque([(start[0], start[1], 0)])
    visited.add((start[0], start[1]))

    while queue:
        x, y, moves = queue.popleft()

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            while 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] != '#':
                nx += dx
                ny += dy
            nx -= dx
            ny -= dy
            if (nx, ny) == (x, y):
                continue
            if (nx, ny) == end:
                return moves + 1
            if (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny, moves + 1))

    return -1
