def min_slides(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    start, end = None, None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if not start or not end:
        return -1

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def get_neighbors(pos):
        i, j = pos
        neighbors = []
        for dx, dy in directions:
            ni, nj = i + dx, j + dy
            if 0 <= ni < rows and 0 <= nj < cols and grid[ni][nj] != '#':
                ni2, nj2 = ni, nj
                while 0 <= ni2 < rows and 0 <= nj2 < cols and grid[ni2][nj2] != '#':
                    ni2 += dx
                    nj2 += dy
                ni2 -= dx
                nj2 -= dy
                if (ni2, nj2) != (i, j):
                    neighbors.append((ni2, nj2))
        return neighbors

    visited = set()
    queue = deque([(start, 0)])
    visited.add(start)

    while queue:
        pos, moves = queue.popleft()
        if pos == end:
            return moves
        for neighbor in get_neighbors(pos):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, moves + 1))

    return -1
