import math
import re
import ast

def evaluate_formula(formula: str, x: float) -> float:
    # Replace x with the variable name 'x' in the formula
    formula = formula.replace('x', 'x')

    # Define a custom function to replace the variable x with its value
    def substitute_x(node):
        if isinstance(node, ast.Expression):
            return substitute_x(node.body)
        elif isinstance(node, ast.UnaryOp):
            return ast.UnaryOp(op=substitute_x(node.op), operand=substitute_x(node.operand))
        elif isinstance(node, ast.BinOp):
            return ast.BinOp(left=substitute_x(node.left), op=node.op, right=substitute_x(node.right))
        elif isinstance(node, ast.UnaryExpr):
            return substitute_x(node.operand)
        elif isinstance(node, ast.Call):
            if isinstance(node.func, ast.Name) and node.func.id in ['sqrt', 'abs', 'sin', 'cos']:
                return ast.Call(func=node.func, args=[substitute_x(node.args[0])], keywords=[])
            else:
                raise ValueError("Invalid function name")
        elif isinstance(node, ast.Name) and node.id == 'x':
            return ast.Name(id='x', ctx=ast.Load())
        elif isinstance(node, ast.Num):
            return node
        else:
            raise ValueError("Invalid formula structure")

    # Check if the formula contains only allowed characters
    if re.search(r'[^0-9.+\-*/\(\)\s\w]', formula):
        raise ValueError("Invalid formula")

    # Check if the formula contains any other variable than x
    if re.search(r'[^x\s0-9.+\-*/\(\)\s]', formula):
        raise ValueError("Invalid formula")

    # Parse the formula into an AST
    try:
        tree = ast.parse(formula, mode='eval')
    except SyntaxError:
        raise ValueError("Invalid formula")

    # Substitute x with its value in the AST
    try:
        tree = substitute_x(tree)
    except ValueError:
        raise ValueError("Invalid formula")

    # Evaluate the AST with x replaced by the given value
    try:
        result = eval(compile(tree, '<string>', 'eval'), {'x': x, 'sqrt': math.sqrt, 'abs': abs, 'sin': math.sin, 'cos': math.cos})
    except ZeroDivisionError:
        raise ZeroDivisionError("Division by zero")
    except Exception as e:
        raise ValueError("Invalid formula")

