import re

def tokenize_code(source: str) -> list[tuple[str, str]]:
    if not source.strip():
        return []

    # Define regex pattern for tokens
    pattern = r"""
        (==|!=|<=|>=|<<|>>|&&|\|\||\+\+|--|\/\/|\*\*|<<=|>>=|&&=|\|\|=|\/\/=|\*\*=|<<=|>>=|<=|>=|==|!=|<<|>>|&&|\|\||\+\+|--|\/\/|\*\*|<|>|=|\+|-|\*|/|,|\(|\)|_)  # Operators
        |([_a-zA-Z][a-zA-Z0-9_]*?)  # Names
        |(\d+\.\d+|\d+)  # Numbers
        |(\.)  # Dot (only allowed in numbers)
    """

    # Compile the regex with verbose flag
    regex = re.compile(pattern, re.VERBOSE)

    tokens = []
    for match in regex.finditer(source):
        token = match.group()
        if token:
            if match.group(1):
                tokens.append(('OP', token))
            elif match.group(2):
                tokens.append(('NAME', token))
            elif match.group(3):
                tokens.append(('NUMBER', token))
            elif match.group(4):
                # Check if the dot is part of a number
                if any(t[1] == '.' and not (t[1] == '.' and t[0] == 'NUMBER') for t in tokens):
                    raise ValueError("Invalid character '.'")
                tokens.append(('NUMBER', token))

    # Check for invalid characters
    for token in tokens:
        if token[0] != 'NUMBER' and token[0] != 'NAME' and token[0] != 'OP':
            raise ValueError("Invalid token")

    return tokens
