import builtins

def matches_filter(expression: str, record: dict) -> bool:
    # Check if all variables in the expression are keys in the record
    variables = re.findall(r'\b([a-zA-Z_][a-zA-Z0-9_]*)\b', expression)
    for var in variables:
        if var not in record:
            raise ValueError(f"Unknown variable: {var}")

    # Replace variables in the expression with their values from the record
    # and evaluate the expression
    try:
        # Create a new namespace with the record and built-in functions
        namespace = {
            **record,
            **{k: v for k, v in builtins.__dict__.items() if not k.startswith('__')}
        }
        # Parse and evaluate the expression
        tree = ast.parse(expression, mode='eval')
        # Replace variable references with their values
        for node in ast.walk(tree):
            if isinstance(node, ast.Name):
                if node.id in namespace:
                    node.id = str(namespace[node.id])
        # Evaluate the expression
        return eval(compile(tree, '<string>', 'eval'))
    except (SyntaxError, NameError, TypeError, ValueError):
        raise ValueError("Invalid expression")
