import ipaddress

def is_public_ip(ip_str: str) -> bool:
    try:
        # Try to parse as IPv4
        ip = ipaddress.IPv4Address(ip_str)
        # Check if IPv4 is public
        return not (ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_multicast or ip.is_unspecified or ip.is_reserved or ip.is_documentation or ip == ipaddress.IPv4Address('255.255.255.255'))
    except ValueError:
        try:
            # Try to parse as IPv6
            ip = ipaddress.IPv6Address(ip_str)
            # Check if IPv6 is public
            return not (ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_multicast or ip.is_unspecified or ip.is_reserved or ip.is_documentation)
        except ValueError:
            # Check if it's an IPv4-mapped IPv6 address
            if ip_str.startswith('::ffff:') and len(ip_str) == len('::ffff:0.0.0.0'):
                ipv4_part = ip_str[7:-1]
                try:
                    ip = ipaddress.IPv4Address(ipv4_part)
                    return not (ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_multicast or ip.is_unspecified or ip.is_reserved or ip.is_documentation or ip == ipaddress.IPv4Address('255.255.255.255'))
                except ValueError:
                    return False
            return False
