def parse_csv(text: str) -> list[list[str]]:
    if not text:
        return []

    records = []
    lines = text.split('\n')
    i = 0
    while i < len(lines):
        line = lines[i]
        record = []
        j = 0
        while j < len(line):
            if line[j] == '"':
                # Start of a quoted field
                j += 1
                field = ''
                while j < len(line):
                    if line[j] == '"':
                        j += 1
                        if j < len(line) and line[j] == '"':
                            field += '"'
                            j += 1
                        else:
                            break
                    else:
                        field += line[j]
                        j += 1
                record.append(field)
            elif line[j] == ',':
                # End of an unquoted field
                record.append('')
                j += 1
            else:
                # Start of an unquoted field
                start = j
                while j < len(line) and line[j] != ',' and line[j] != '\n':
                    j += 1
                record.append(line[start:j])
        records.append(record)
        i += 1
    return records
