import re
from urllib.parse import urlparse

def is_allowed_webhook(url: str) -> bool:
    # Check if URL starts with https:// (case-insensitive)
    if not url.lower().startswith('https://'):
        return False

    # Check for backslashes, spaces, and control characters
    if '\\' in url or ' ' in url or any(ord(c) < 32 or ord(c) == 127 for c in url):
        return False

    # Parse URL
    parsed = urlparse(url)
    if parsed.scheme != 'https':
        return False

    # Extract host
    host = parsed.hostname
    if not host:
        return False

    # Check for user@ or user:password@ prefix
    if '@' in host:
        host = host.split('@')[-1]

    # Check if host ends with .localhost (case-insensitive)
    if host.lower().endswith('.localhost'):
        return False

    # Check if host is 'localhost' (case-insensitive)
    if host.lower() == 'localhost':
        return False

    # Check if host is a valid DNS name
    # Split host into labels
    labels = host.split('.')
    if len(labels) < 2:
        return False

    # Check each label
    for label in labels[:-1]:
        if not re.fullmatch(r'[a-zA-Z0-9-]+', label):
            return False

    # Check last label (domain)
    if not re.fullmatch(r'[a-zA-Z]+', labels[-1]):
        return False

    # Check port
    if parsed.port is not None and parsed.port != 443:
        return False

    return True

import re
from urllib.parse import urlparse

def is_allowed_webhook(url: str) -> bool:
    # Check if URL starts with https:// (case-insensitive)
    if not url.lower().startswith('https://'):
        return False

    # Check for backslashes, spaces, and control characters
    if '\\' in url or ' ' in url or any(ord(c) < 32 or ord(c) == 127 for c in url):
        return False

    # Parse URL
    parsed = urlparse(url)
    if parsed.scheme != 'https':
        return False

    # Extract host
    host = parsed.hostname
    if not host:
        return False

    # Handle user@ or user:password@ prefix
    if '@' in host:
        host = host.split('@')[-1]

    # Remove trailing dot if present
    if host.endswith('.'):
        host = host[:-1]

    # Check if host is localhost or ends with .localhost
    if host.lower() == 'localhost' or host.lower().endswith('.localhost'):
        return False

    # Check if host is a valid DNS name
    if not re.match(r'^([a-zA-Z0-9-]+\.)*[a-zA-Z0-9-]+$', host):
        return False

    # Check if host has at least two labels
    if len(host.split('.')) < 2:
        return False

    # Check if last label consists only of letters
    last_label = host.split('.')[-1]
    if not last_label.isalpha():
        return False

    # Check port
    if parsed.port is not None and parsed.port != 443:
        return False

    return True

