import ast
import re

def matches_filter(expression: str, record: dict) -> bool:
    # Check if all variables in the expression are present in the record
    variables = re.findall(r'\b([a-zA-Z_]\w*)\b', expression)
    for var in set(variables):
        if var not in record:
            raise ValueError(f"Variable '{var}' not found in record")

    # Create a new namespace with the record's variables
    namespace = {key: value for key, value in record.items()}

    # Parse the expression into an AST and evaluate it
    try:
        tree = ast.parse(expression, mode='eval')
        # Replace occurrences of variable names with their values
        for node in ast.walk(tree):
            if isinstance(node, ast.Name):
                if node.id in namespace:
                    node.id = str(namespace[node.id])
        # Evaluate the modified AST
        result = eval(compile(tree, '<string>', 'eval'))
        return bool(result)
    except (SyntaxError, NameError, TypeError, ValueError):
        raise ValueError("Invalid expression")
