def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix:
        return []
    n = len(matrix)
    result = [[0]*n for _ in range(n)]
    for ring in range((n + 1) // 2):
        top = ring
        bottom = n - 1 - ring
        left = ring
        right = n - 1 - ring
        if top == bottom:
            # Single row
            for i in range(n):
                result[ring][i] = matrix[ring][i]
            continue
        if left == right:
            # Single column
            for i in range(n):
                result[i][ring] = matrix[i][ring]
            continue
        # Collect elements of the ring
        ring_elements = []
        for i in range(top, bottom + 1):
            ring_elements.append(matrix[top][i])
        for i in range(top + 1, bottom + 1):
            ring_elements.append(matrix[i][right])
        for i in range(right - 1, left - 1, -1):
            ring_elements.append(matrix[bottom][i])
        for i in range(bottom - 1, top, -1):
            ring_elements.append(matrix[i][left])
        # Rotate the elements
        k = k % len(ring_elements)
        rotated_elements = ring_elements[-k:] + ring_elements[:-k]
        # Place rotated elements back into the result
        idx = 0
        for i in range(top, bottom + 1):
            result[top][i] = rotated_elements[idx]
            idx += 1
        for i in range(top + 1, bottom + 1):
            result[i][right] = rotated_elements[idx]
            idx += 1
        for i in range(right - 1, left - 1, -1):
            result[bottom][i] = rotated_elements[idx]
            idx += 1
        for i in range(bottom - 1, top, -1):
            result[i][left] = rotated_elements[idx]
            idx += 1
    return result
