            stock[item] += quantity
            # Fulfill waiting orders for this item
            while waiting and waiting[0][0] == item:
                order_item, order_qty = waiting.pop(0)
                if stock[item] >= order_qty:
                    stock[item] -= order_qty
                else:
                    # Not enough stock, re-add to waiting
                    waiting.insert(0, (order_item, order_qty))
                    break
        else:  # 'order'
            if item not in stock:
                stock[item] = 0
            if stock[item] >= quantity:
                stock[item] -= quantity
            else:
                waiting.append((item, quantity))

