def is_allowed_webhook(url: str) -> bool:
    # Check if URL starts with https:// (case-insensitive)
    if not url.lower().startswith('https://'):
        return False

    # Check for backslash, space, or control characters
    if re.search(r'[\s\\\x00-\x1F\x7F-\x9F]', url):
        return False

    parsed = urlparse(url)
    if not parsed.scheme or not parsed.netloc:
        return False

    # Extract host part (after user:password@ and before port)
    host = parsed.netloc
    if '@' in host:
        host = host.split('@')[-1]

    # Check if host ends with a dot
    if not host.endswith('.'):
        return False

    # Split host into labels
    labels = host[:-1].split('.')
    if len(labels) < 2:
        return False

    # Check each label
    for i, label in enumerate(labels):
        if not label:
            return False
        if not re.fullmatch(r'[a-zA-Z0-9-]+', label):
            return False
        if i == len(labels) - 1:
            if not re.fullmatch(r'[a-zA-Z]+', label):
                return False

    # Check if host is localhost or ends with .localhost
    if host.lower() == 'localhost' or host.lower().endswith('.localhost'):
        return False

    # Check port
    if parsed.port:
        if parsed.port != 443:
            return False

