import re

def tokenize_code(source: str) -> list[tuple[str, str]]:
    if not source.strip():
        return []

    # Define the regex pattern for tokens
    pattern = r"""
        (==|!=|<=|>=|[\+\-\*\/\<\>\=\(\),])  # Two-character operators and single-character operators
        |(?P<NUMBER>(\d+\.\d+|\d+))         # Numbers (including decimal)
        |(?P<NAME>[a-zA-Z_][a-zA-Z0-9_]*)  # Names (letters, digits, underscores)
        |\.                               # Dot (only allowed in numbers)
    """

    # Compile the regex with verbose flag
    token_regex = re.compile(pattern, re.VERBOSE)

    tokens = []
    for match in token_regex.finditer(source):
        kind = match.lastgroup
        text = match.group(kind)

        if kind == 'NUMBER':
            if '.' in text and text.count('.') > 1:
                raise ValueError("Invalid number format")
            tokens.append(('NUMBER', text))
        elif kind == 'NAME':
            tokens.append(('NAME', text))
        elif kind == 'OP':
            tokens.append(('OP', text))
        elif kind == 'DOT':
            if '.' not in text or text.count('.') > 1:
                raise ValueError("Invalid use of '.'")

