def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    # Determine column widths
    col_widths = [max(len(cell) for cell in col) for col in zip(*rows)]

    # Format each cell based on alignment
    def format_cell(cell: str, width: int, align: str) -> str:
        padding = width - len(cell)
        if align == 'l':
            return cell.ljust(width)
        elif align == 'r':
            return cell.rjust(width)
        elif align == 'c':
            left_pad = padding // 2
            right_pad = padding - left_pad
            return cell.rjust(width - left_pad).ljust(width)

    # Format each row
    formatted_rows = []
    for i, row in enumerate(rows):
        formatted_cells = [format_cell(row[j], col_widths[j], aligns[j]) for j in range(len(row))]
        formatted_row = " | ".join(formatted_cells)
        formatted_rows.append(formatted_row)

    return "\n".join(formatted_rows)
