def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    # Determine column widths
    col_widths = [max(len(cell) for cell in col) for col in zip(*rows)]

    # Format each row based on alignment
    formatted_rows = []
    for i, row in enumerate(rows):
        line = []
        for j, cell in enumerate(row):
            width = col_widths[j]
            align = aligns[j]
            if align == 'l':
                line.append(cell.ljust(width))
            elif align == 'r':
                line.append(cell.rjust(width))
            elif align == 'c':
                spaces = width - len(cell)
                if spaces % 2 == 0:
                    left, right = spaces // 2, spaces // 2
                else:
                    left, right = spaces // 2, spaces // 2 + 1
                line.append(' ' * left + cell + ' ' * right)
        formatted_rows.append(' | '.join(line))

    return '\n'.join(formatted_rows)
