def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    # Determine column widths
    col_widths = [max(len(cell) for cell in col) for col in zip(*rows)]

    # Format each cell based on alignment
    def format_cell(text, width, align):
        if align == 'l':
            return text.ljust(width)
        elif align == 'r':
            return text.rjust(width)
        elif align == 'c':
            pad = width - len(text)
            left_pad = pad // 2
            right_pad = pad - left_pad
            return ' ' * left_pad + text + ' ' * right_pad

    # Format each row
    formatted_rows = []
    for i, row in enumerate(rows):
        formatted_cells = [
            format_cell(row[j], col_widths[j], aligns[j]) for j in range(len(row))
        ]
        formatted_row = ' | '.join(formatted_cells)
        formatted_rows.append(formatted_row)

    return '\n'.join(formatted_rows)
