import re

def tokenize_code(source: str) -> list[tuple[str, str]]:
    if not source.strip():
        return []

    # Define the regex pattern for tokenizing
    pattern = r"""
        (==|!=|<=|>=)      # Two-character operators
        |([()+,=])         # Single-character operators
        |(\d+\.\d+|\d+)    # Numbers (including those with decimal points)
        |([_a-zA-Z][_a-zA-Z0-9]*)  # Names
        |(\.)              # Single dot (not part of a number)
        |([^a-zA-Z0-9_])   # Any other character
    """

    tokens = []
    for match in re.finditer(pattern, source, re.VERBOSE):
        kind, text = None, match.group()
        if text in ('==', '!=', '<=', '>='):
            kind = 'OP'
        elif text in '+-*/<>=() ,':
            kind = 'OP'
        elif re.fullmatch(r'\d+\.\d+|\d+', text):
            kind = 'NUMBER'
        elif re.fullmatch(r'[_a-zA-Z][_a-zA-Z0-9]*', text):
            kind = 'NAME'
        elif text == '.':
            raise ValueError("Invalid character '.'")
        else:
            raise ValueError(f"Invalid character: {text}")

        tokens.append((kind, text))

    # Check for invalid characters
    for kind, text in tokens:
        if kind != 'OP' and kind != 'NUMBER' and kind != 'NAME':
            raise ValueError(f"Invalid token: {text}")

    return tokens
