def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    ip = 0
    instruction_count = 0
    max_instructions = 1000

    while instruction_count < max_instructions:
        if ip < 0 or ip >= len(program):
            break
        instruction = program[ip]
        instruction_count += 1
        if instruction.startswith("PUSH "):
            _, n = instruction.split()
            stack.append(int(n))
        elif instruction == "POP":
            if not stack:
                return None
            stack.pop()
        elif instruction == "DUP":
            if not stack:
                return None
            stack.append(stack[-1])
        elif instruction == "SWAP":
            if len(stack) < 2:
                return None
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif instruction.startswith("ADD"):
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)
        elif instruction.startswith("SUB"):
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
        elif instruction.startswith("MUL"):
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)
        elif instruction.startswith("JMP "):
            _, t = instruction.split()
            ip = int(t)
        elif instruction.startswith("JZ "):
            _, t = instruction.split()
            if stack and stack[-1] == 0:
                ip = int(t)
            else:
                ip += 1
        else:
            return None
        ip += 1

    return stack if ip >= len(program) else None
