def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    waiting = []
    order_index = 0

    for event in events:
        kind, item, quantity = event

        if kind == 'receive':
            if item not in stock:
                stock[item] = 0
            stock[item] += quantity
            # Fulfill pending orders for this item
            while waiting and waiting[0][0] == item:
                pending_item, pending_quantity = waiting.pop(0)
                if stock[pending_item] >= pending_quantity:
                    stock[pending_item] -= pending_quantity
                else:
                    waiting.insert(0, (pending_item, pending_quantity))
                    break
        else:  # 'order'
            if item not in stock:
                stock[item] = 0
            if stock[item] >= quantity:
                stock[item] -= quantity
            else:
                waiting.append((item, quantity))

    # Ensure all items in stock are included, even if their quantity is 0
    all_items = set(stock.keys()).union(set(item for item, _ in waiting))
    stock = {item: stock.get(item, 0) for item in all_items}
    # Sort waiting list by order they were placed
    waiting.sort(key=lambda x: x[1])
    return stock, waiting
