def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    waiting = {}

    for kind, item, quantity in events:
        if kind == 'receive':
            if item not in stock:
                stock[item] = 0
            stock[item] += quantity
            # Process pending orders for this item
            while item in waiting and stock[item] >= waiting[item][0]:
                order_quantity = waiting[item][0]
                stock[item] -= order_quantity
                waiting[item] = waiting[item][1:]
        else:  # 'order'
            if item not in stock:
                stock[item] = 0
            if item not in waiting:
                waiting[item] = []
            if stock[item] >= quantity:
                stock[item] -= quantity
            else:
                waiting[item].append((quantity,))  # Store as (quantity, )

    # Convert waiting to list of tuples (item, quantity)
    waiting_list = []
    for item in waiting:
        for qty in waiting[item]:
            waiting_list.append((item, qty))

    # Ensure all items are in stock even if their quantity is 0
    all_items = set()
    for event in events:
        all_items.add(event[1])
    for item in all_items:
        if item not in stock:
            stock[item] = 0

    return (stock, waiting_list)
