def run_bank_ops(balances: dict[str, int], ops: list[tuple]) -> tuple[dict[str, int], list[int]]:
    final_balances = balances.copy()
    frozen = {acc: False for acc in balances}
    failed = []

    for i, op in enumerate(ops):
        if op[0] not in ('deposit', 'withdraw', 'transfer', 'freeze', 'unfreeze'):
            failed.append(i)
            continue

        if op[0] == 'deposit':
            acc, amount = op[1], op[2]
            if amount <= 0 or acc not in final_balances or frozen[acc]:
                failed.append(i)
            else:
                final_balances[acc] += amount

        elif op[0] == 'withdraw':
            acc, amount = op[1], op[2]
            if amount <= 0 or acc not in final_balances or frozen[acc]:
                failed.append(i)
            else:
                if final_balances[acc] - amount < 0:
                    failed.append(i)
                else:
                    final_balances[acc] -= amount

        elif op[0] == 'transfer':
            src, target, amount = op[1], op[2], op[3]
            if src == target or amount <= 0 or src not in final_balances or target not in final_balances or frozen[src] or frozen[target]:
                failed.append(i)
            else:
                if final_balances[src] - amount - 2 < 0:
                    failed.append(i)
                else:
                    final_balances[src] -= amount + 2
                    final_balances[target] += amount

        elif op[0] == 'freeze':
            acc = op[1]
            if acc in final_balances and not frozen[acc]:
                frozen[acc] = True

        elif op[0] == 'unfreeze':
            acc = op[1]
            if acc in final_balances and frozen[acc]:
                frozen[acc] = False

    return final_balances, sorted(failed)
